//! Property-test generators for Vertep charts, shared by every crate that tests a chart surface
//! (SCXML, RDF) or the interpreter.
//!
//! Two flavours:
//!
//! - [`arb_chart`] / [`arb_chart_with`]: **well-formed** charts. Unique state identifiers
//!   (declared `s<n>` or generated by [`vertep_core::identity::assign_generated_ids`]);
//!   transition targets that exist; `initial` attributes and `<initial>` transitions that
//!   target proper descendants of their state; history states only inside compound and
//!   parallel states, with at most one default transition (no event, no condition) targeting
//!   a descendant of the history's parent; final states with only `onentry`, `onexit` and
//!   `donedata`; compound and parallel states with at least one non-history child; mutually
//!   exclusive attributes never both set; and charts in the *canonical surface form*
//!   described below. These charts are what every surface must round-trip.
//! - [`arb_any_chart`] / [`arb_any_chart_with`]: **any IR**. Every field independent, state
//!   kinds anywhere, identifiers from a small pool (duplicates and dangling targets
//!   included), extension positions arbitrary. Use it for robustness properties (no panics,
//!   errors instead of garbage), not for round trips.
//!
//! # Canonical surface form
//!
//! The IR can hold distinctions no XML surface can carry. Well-formed charts avoid them:
//!
//! - extension lists hold attributes first, sorted by `(ns, local)` and unique, then elements
//!   whose `position` is their index among the owner's element children in the IR's child
//!   order (see [`canonicalize_extensions`]);
//! - "explicit" flags are set whenever the value is not the default (`datamodel != "null"`,
//!   late binding, internal transitions);
//! - inline bodies are never empty or whitespace-only, text bodies never contain markup, and
//!   XML bodies are in the canonical serialization (self-contained namespace declarations,
//!   double-quoted attributes, minimal escaping);
//! - a `src` on `<script>`, `<data>` or `<invoke>` comes without inline content (read such
//!   charts back with a resolver that defers), and `<content>` never has a `src`;
//! - no declared identifier starts with the generated prefix `_vt.`.
//!
//! All spans are [`Span::NONE`]; spans never take part in equality.

use std::collections::BTreeSet;

use proptest::collection::vec;
use proptest::option;
use proptest::prelude::*;
use proptest::sample::Index;
use vertep_core::identity::assign_generated_ids;
use vertep_core::ir::{
    Binding, Chart, Content, Data, DoneData, Exec, ExecKind, Extension, ExtensionValue,
    HistoryType, IfBranch, Initial, Invoke, Param, Script, Send, Span, State, StateElement,
    Transition, TransitionType, VT_NS,
};

/// Size and content limits for generated charts.
#[derive(Clone, Debug)]
pub struct ChartConfig {
    /// Maximum nesting depth of states below the root.
    pub max_depth: u32,
    /// Maximum number of top-level states (at least one is generated).
    pub max_top_states: usize,
    /// Maximum number of non-history children of a compound or parallel state.
    pub max_children: usize,
    /// Maximum number of transitions per state.
    pub max_transitions: usize,
    /// Maximum number of targets per ordinary transition. Values above 1 may produce target
    /// sets that do not form a legal configuration.
    pub max_targets: usize,
    /// Maximum number of executable content elements per block.
    pub max_block: usize,
    /// Maximum nesting of `<if>` and `<foreach>`.
    pub exec_depth: u32,
    /// Datamodel names to choose from.
    pub datamodels: Vec<String>,
    /// Generate `vt:` and foreign extension attributes and elements.
    pub extensions: bool,
    /// Generate `<invoke>` elements.
    pub invokes: bool,
}

impl Default for ChartConfig {
    fn default() -> Self {
        ChartConfig {
            max_depth: 3,
            max_top_states: 3,
            max_children: 3,
            max_transitions: 2,
            max_targets: 1,
            max_block: 2,
            exec_depth: 2,
            datamodels: vec!["null".to_owned(), "ecmascript".to_owned()],
            extensions: true,
            invokes: true,
        }
    }
}

/// Namespaces used for extension nodes: the Vertep namespace and two foreign ones.
pub const EXTENSION_NAMESPACES: [&str; 3] = [VT_NS, "urn:example:ext", "http://example.org/ns#"];

/// Prefix used to mark a target that the post-processing pass replaces with a real state id.
const PLACEHOLDER: char = '?';

/// Data ids are global to a chart (W3C SCXML 5.2), so rename later duplicates.
fn unique_data_ids(chart: &mut Chart) {
    fn fix(data: &mut [Data], seen: &mut BTreeSet<String>) {
        for d in data {
            let mut id = d.id.clone();
            let mut n = 0usize;
            while !seen.insert(id.clone()) {
                n += 1;
                id = format!("{}_{n}", d.id);
            }
            d.id = id;
        }
    }
    fn walk(states: &mut [State], seen: &mut BTreeSet<String>) {
        for st in states {
            fix(&mut st.data, seen);
            walk(&mut st.children, seen);
        }
    }
    let mut seen = BTreeSet::new();
    fix(&mut chart.data, &mut seen);
    walk(&mut chart.states, &mut seen);
}

// ==================================================================== public entry points

/// Well-formed charts with the default [`ChartConfig`].
pub fn arb_chart() -> BoxedStrategy<Chart> {
    arb_chart_with(ChartConfig::default())
}

/// Well-formed charts with the given limits.
pub fn arb_chart_with(cfg: ChartConfig) -> BoxedStrategy<Chart> {
    let g = Gen { cfg, any: false };
    g.chart().prop_map(finish_well_formed).boxed()
}

/// Arbitrary IR values with the default [`ChartConfig`]; see the crate docs.
pub fn arb_any_chart() -> BoxedStrategy<Chart> {
    arb_any_chart_with(ChartConfig::default())
}

/// Arbitrary IR values with the given limits.
pub fn arb_any_chart_with(cfg: ChartConfig) -> BoxedStrategy<Chart> {
    let g = Gen { cfg, any: true };
    g.chart()
}

/// One block of executable content as it appears in well-formed charts (extension positions
/// set to their block index).
pub fn arb_block() -> BoxedStrategy<Vec<Exec>> {
    let g = Gen {
        cfg: ChartConfig::default(),
        any: false,
    };
    g.block()
        .prop_map(|mut b| {
            fix_block(&mut b);
            b
        })
        .boxed()
}

/// Expression text: printable ASCII including XML metacharacters, plus some whitespace and
/// non-ASCII characters.
pub fn arb_expr() -> BoxedStrategy<String> {
    prop_oneof![
        3 => "[ -~]{0,12}",
        1 => "[a-z\n\t é中😀<&\"']{0,8}",
    ]
    .boxed()
}

/// An event descriptor: `*`, or dot-separated tokens with an optional `.*` suffix.
pub fn arb_event_descriptor() -> BoxedStrategy<String> {
    prop_oneof![
        1 => Just("*".to_owned()),
        6 => "[a-z][a-z0-9_]{0,5}(\\.[a-z0-9_]{1,4}){0,2}(\\.\\*)?",
    ]
    .boxed()
}

/// All state identifiers of a chart in document order.
pub fn state_ids(chart: &Chart) -> Vec<String> {
    fn walk(states: &[State], out: &mut Vec<String>) {
        for s in states {
            out.push(s.id.clone());
            walk(&s.children, out);
        }
    }
    let mut out = Vec::new();
    walk(&chart.states, &mut out);
    out
}

/// Bring every extension list of the chart into canonical surface form: attributes first,
/// sorted by `(ns, local)` with duplicates removed, then elements in their current order with
/// positions repaired to be strictly increasing and to fit among the owner's element
/// children; extension elements in executable content blocks get their block index.
///
/// Element children are counted in the IR's child order: for the root, a non-empty `data`
/// block, the `script` and the states; for a state, `initial_element`, a non-empty `data`
/// block, each `onentry` and `onexit` block, transitions, child states, invokes and
/// `donedata`; for `<initial>`, its transition; for an invoke, params, `content` when it has
/// no `src`, and a non-empty `finalize`; for `<send>`, params and `content`.
pub fn canonicalize_extensions(chart: &mut Chart) {
    let n = usize::from(!chart.data.is_empty())
        + usize::from(chart.script.is_some())
        + chart.states.len();
    fix_list(&mut chart.extensions, n);
    for d in &mut chart.data {
        fix_list(&mut d.extensions, 0);
    }
    for s in &mut chart.states {
        fix_state(s);
    }
}

// ==================================================================== post-processing

fn finish_well_formed(mut chart: Chart) -> Chart {
    let mut counter = 0usize;
    name_states(&mut chart.states, &mut counter);
    unique_data_ids(&mut chart);
    assign_generated_ids(&mut chart);
    let all = state_ids(&chart);
    let mut top_desc = Vec::new();
    for s in &chart.states {
        if !is_history(s) {
            top_desc.push(s.id.clone());
        }
        descendants(s, &mut top_desc);
    }
    chart.initial = resolve_targets(&chart.initial, &top_desc);
    resolve_states(&mut chart.states, &top_desc, &all);
    canonicalize_extensions(&mut chart);
    chart
}

/// Declared states (non-empty placeholder id) become `s<n>` in document order; anonymous
/// states keep an empty id for the generator.
fn name_states(states: &mut [State], counter: &mut usize) {
    for s in states {
        if !s.id.is_empty() {
            s.id = format!("s{counter}");
            *counter += 1;
        }
        name_states(&mut s.children, counter);
    }
}

fn is_history(s: &State) -> bool {
    matches!(s.element, StateElement::History(_))
}

fn descendants(s: &State, out: &mut Vec<String>) {
    for c in &s.children {
        if !is_history(c) {
            out.push(c.id.clone());
        }
        descendants(c, out);
    }
}

fn resolve_targets(targets: &[String], pool: &[String]) -> Vec<String> {
    if pool.is_empty() {
        return Vec::new();
    }
    targets
        .iter()
        .map(|t| match t.strip_prefix(PLACEHOLDER) {
            Some(n) => {
                let n: usize = n.parse().unwrap_or(0);
                pool[n % pool.len()].clone()
            }
            None => t.clone(),
        })
        .collect()
}

fn resolve_states(states: &mut [State], parent_desc: &[String], all: &[String]) {
    for s in states {
        let mut desc = Vec::new();
        descendants(s, &mut desc);
        s.initial = resolve_targets(&s.initial, &desc);
        if let Some(i) = &mut s.initial_element {
            i.transition.targets = resolve_targets(&i.transition.targets, &desc);
        }
        let pool = if is_history(s) { parent_desc } else { all };
        for t in &mut s.transitions {
            t.targets = resolve_targets(&t.targets, pool);
        }
        resolve_states(&mut s.children, &desc, all);
    }
}

fn fix_list(list: &mut Vec<Extension>, n: usize) {
    let mut attrs: Vec<Extension> = Vec::new();
    let mut elements: Vec<Extension> = Vec::new();
    for x in list.drain(..) {
        match x.value {
            ExtensionValue::Attribute(_) => attrs.push(Extension { position: 0, ..x }),
            ExtensionValue::Element(_) => elements.push(x),
        }
    }
    attrs.sort_by(|a, b| (&a.ns, &a.local).cmp(&(&b.ns, &b.local)));
    attrs.dedup_by(|a, b| a.ns == b.ns && a.local == b.local);
    let mut next_min = 0u32;
    for (i, x) in elements.iter_mut().enumerate() {
        let max = u32::try_from(n + i).unwrap_or(u32::MAX);
        x.position = x.position.clamp(next_min, max.max(next_min));
        next_min = x.position + 1;
    }
    list.extend(attrs);
    list.extend(elements);
}

fn fix_block(b: &mut [Exec]) {
    for (i, x) in b.iter_mut().enumerate() {
        let n = match &mut x.kind {
            ExecKind::Send(s) => s.params.len() + usize::from(s.content.is_some()),
            ExecKind::If { branches } => {
                for br in branches.iter_mut() {
                    fix_block(&mut br.body);
                }
                0
            }
            ExecKind::Foreach { body, .. } => {
                fix_block(body);
                0
            }
            ExecKind::Extension(e) => {
                e.position = u32::try_from(i).unwrap_or(u32::MAX);
                0
            }
            _ => 0,
        };
        fix_list(&mut x.extensions, n);
    }
}

fn fix_state(s: &mut State) {
    let n = usize::from(s.initial_element.is_some())
        + usize::from(!s.data.is_empty())
        + s.onentry.len()
        + s.onexit.len()
        + s.transitions.len()
        + s.children.len()
        + s.invokes.len()
        + usize::from(s.donedata.is_some());
    fix_list(&mut s.extensions, n);
    if let Some(i) = &mut s.initial_element {
        fix_list(&mut i.extensions, 1);
        fix_list(&mut i.transition.extensions, 0);
        fix_block(&mut i.transition.body);
    }
    for d in &mut s.data {
        fix_list(&mut d.extensions, 0);
    }
    for b in s.onentry.iter_mut().chain(s.onexit.iter_mut()) {
        fix_block(b);
    }
    for t in &mut s.transitions {
        fix_list(&mut t.extensions, 0);
        fix_block(&mut t.body);
    }
    for inv in &mut s.invokes {
        let n = inv.params.len()
            + usize::from(inv.content.is_some() && inv.src.is_none())
            + usize::from(!inv.finalize.is_empty());
        fix_list(&mut inv.extensions, n);
        fix_block(&mut inv.finalize);
    }
    for c in &mut s.children {
        fix_state(c);
    }
}

// ==================================================================== generators

/// Generator state: the limits and the flavour.
#[derive(Clone)]
struct Gen {
    cfg: ChartConfig,
    /// Any-IR flavour: independent fields, no structural rules.
    any: bool,
}

type Opt2 = (Option<String>, Option<String>);

impl Gen {
    // ------------------------------------------------------------ small values

    fn name(&self) -> BoxedStrategy<String> {
        "[a-z][a-z0-9_]{0,5}".boxed()
    }

    fn text_body(&self) -> BoxedStrategy<String> {
        "[a-zA-Z0-9 {}\\[\\]:,\"'&<>.]{1,12}"
            .prop_filter("not whitespace-only", |s| !s.trim().is_empty())
            .boxed()
    }

    /// A body for `<data>`, `<assign>` or `<content>`: text or canonical XML.
    fn body(&self) -> BoxedStrategy<String> {
        prop_oneof![2 => self.text_body(), 1 => xml_body()].boxed()
    }

    /// Two attributes that exclude each other: at most one set (any flavour: independent).
    fn pair(&self, a: BoxedStrategy<String>, b: BoxedStrategy<String>) -> BoxedStrategy<Opt2> {
        if self.any {
            (option::of(a), option::of(b)).boxed()
        } else {
            prop_oneof![
                Just((None, None)),
                a.prop_map(|x| (Some(x), None)),
                b.prop_map(|y| (None, Some(y))),
            ]
            .boxed()
        }
    }

    /// Two attributes of which exactly one is set (any flavour: independent).
    fn one_of(&self, a: BoxedStrategy<String>, b: BoxedStrategy<String>) -> BoxedStrategy<Opt2> {
        if self.any {
            (option::of(a), option::of(b)).boxed()
        } else {
            prop_oneof![
                a.prop_map(|x| (Some(x), None)),
                b.prop_map(|y| (None, Some(y))),
            ]
            .boxed()
        }
    }

    fn tokens(&self, max: usize) -> BoxedStrategy<Vec<String>> {
        vec(self.name(), 0..=max).boxed()
    }

    fn target(&self) -> BoxedStrategy<String> {
        if self.any {
            prop_oneof!["s[0-9]", Just(String::new()), "[a-z_.]{1,6}"].boxed()
        } else {
            any::<u16>()
                .prop_map(|n| format!("{PLACEHOLDER}{n}"))
                .boxed()
        }
    }

    // ------------------------------------------------------------ extensions

    fn ext_attr(&self) -> BoxedStrategy<Extension> {
        (
            prop::sample::select(EXTENSION_NAMESPACES.to_vec()),
            "[a-z][a-zA-Z0-9]{0,5}",
            arb_expr(),
        )
            .prop_map(|(ns, local, v)| Extension {
                ns: ns.to_owned(),
                local,
                value: ExtensionValue::Attribute(v),
                position: 0,
                span: Span::NONE,
            })
            .boxed()
    }

    fn ext_element(&self) -> BoxedStrategy<Extension> {
        (
            prop::sample::select(EXTENSION_NAMESPACES.to_vec()),
            "[a-z][a-zA-Z0-9]{0,5}",
            xml_children(),
            0u32..6,
        )
            .prop_map(|(ns, local, children, position)| {
                let prefix = if ns == VT_NS { "vt" } else { "ex" };
                let xml = format!(
                    "<{prefix}:{local} xmlns:{prefix}=\"{ns}\"{}",
                    close_element(&format!("{prefix}:{local}"), &children)
                );
                Extension {
                    ns: ns.to_owned(),
                    local,
                    value: ExtensionValue::Element(xml),
                    position,
                    span: Span::NONE,
                }
            })
            .boxed()
    }

    /// Extension attributes only.
    fn ext_attrs(&self) -> BoxedStrategy<Vec<Extension>> {
        if self.cfg.extensions {
            vec(self.ext_attr(), 0..=2).boxed()
        } else {
            Just(Vec::new()).boxed()
        }
    }

    /// Extension attributes and elements.
    fn exts(&self) -> BoxedStrategy<Vec<Extension>> {
        if self.cfg.extensions {
            (vec(self.ext_attr(), 0..=2), vec(self.ext_element(), 0..=1))
                .prop_map(|(mut a, e)| {
                    a.extend(e);
                    a
                })
                .boxed()
        } else {
            Just(Vec::new()).boxed()
        }
    }

    // ------------------------------------------------------------ executable content

    fn block(&self) -> BoxedStrategy<Vec<Exec>> {
        vec(self.exec(), 0..=self.cfg.max_block).boxed()
    }

    fn exec(&self) -> BoxedStrategy<Exec> {
        let g = self.clone();
        let leaf = self.exec_leaf();
        let max_block = self.cfg.max_block;
        leaf.prop_recursive(self.cfg.exec_depth, 16, 3, move |inner| {
            let block = vec(inner, 0..=max_block).boxed();
            prop_oneof![g.if_exec(block.clone()), g.foreach_exec(block)]
        })
        .boxed()
    }

    fn exec_leaf(&self) -> BoxedStrategy<Exec> {
        let mut options: Vec<(u32, BoxedStrategy<Exec>)> = vec![
            (2, self.raise()),
            (2, self.send()),
            (1, self.cancel()),
            (2, self.log()),
            (1, self.assign()),
            (1, self.script_exec()),
        ];
        if self.cfg.extensions {
            let ext = self
                .ext_element()
                .prop_map(|x| Exec::new(ExecKind::Extension(x)))
                .boxed();
            options.push((1, ext));
        }
        proptest::strategy::Union::new_weighted(options).boxed()
    }

    fn with_exts(&self, kind: BoxedStrategy<ExecKind>, elements: bool) -> BoxedStrategy<Exec> {
        let exts = if elements || self.any {
            self.exts()
        } else {
            self.ext_attrs()
        };
        (kind, exts)
            .prop_map(|(kind, extensions)| Exec {
                kind,
                extensions,
                span: Span::NONE,
            })
            .boxed()
    }

    fn raise(&self) -> BoxedStrategy<Exec> {
        let k = arb_event_descriptor()
            .prop_filter("no wildcard", |e| !e.contains('*'))
            .prop_map(|event| ExecKind::Raise { event })
            .boxed();
        self.with_exts(k, true)
    }

    fn send(&self) -> BoxedStrategy<Exec> {
        let any = self.any;
        let attrs = (
            self.pair(self.name(), arb_expr()),
            self.pair("#_internal|#_parent|#_scxml_[a-z]{1,3}".boxed(), arb_expr()),
            self.pair(
                Just("http://www.w3.org/TR/scxml/#SCXMLEventProcessor".to_owned()).boxed(),
                arb_expr(),
            ),
            self.pair(self.name(), self.name()),
            self.pair("[0-9]{1,3}(ms|s)".boxed(), arb_expr()),
        );
        let payload = prop_oneof![
            (self.tokens(2), vec(self.param(), 0..=2)).prop_map(|(n, p)| (n, p, None)),
            self.content()
                .prop_map(|c| (Vec::new(), Vec::new(), Some(c))),
        ];
        let payload = if any {
            (
                self.tokens(2),
                vec(self.param(), 0..=2),
                option::of(self.content()),
            )
                .boxed()
        } else {
            payload.boxed()
        };
        let k = (attrs, payload)
            .prop_map(|((ev, tg, ty, id, de), (namelist, params, content))| {
                ExecKind::Send(Box::new(Send {
                    event: ev.0,
                    eventexpr: ev.1,
                    target: tg.0,
                    targetexpr: tg.1,
                    type_: ty.0,
                    typeexpr: ty.1,
                    id: id.0,
                    idlocation: id.1,
                    delay: de.0,
                    delayexpr: de.1,
                    namelist,
                    params,
                    content,
                }))
            })
            .boxed();
        self.with_exts(k, true)
    }

    fn cancel(&self) -> BoxedStrategy<Exec> {
        let k = self
            .one_of(self.name(), arb_expr())
            .prop_map(|(sendid, sendidexpr)| ExecKind::Cancel { sendid, sendidexpr })
            .boxed();
        self.with_exts(k, true)
    }

    fn log(&self) -> BoxedStrategy<Exec> {
        let k = (option::of(arb_expr()), option::of(arb_expr()))
            .prop_map(|(label, expr)| ExecKind::Log { label, expr })
            .boxed();
        self.with_exts(k, true)
    }

    fn assign(&self) -> BoxedStrategy<Exec> {
        let k = (self.name(), self.one_of(arb_expr(), self.body()))
            .prop_map(|(location, (expr, content))| ExecKind::Assign {
                location,
                expr,
                content,
            })
            .boxed();
        self.with_exts(k, false)
    }

    fn script(&self) -> BoxedStrategy<Script> {
        let body =
            "[ -~]{1,16}".prop_filter("not whitespace-only", |s: &String| !s.trim().is_empty());
        if self.any {
            (option::of(self.name()), option::of(body))
                .prop_map(|(src, body)| Script {
                    src,
                    body,
                    span: Span::NONE,
                })
                .boxed()
        } else {
            prop_oneof![
                Just((None, None)),
                body.prop_map(|b| (None, Some(b))),
                "[a-z]{1,6}\\.js".prop_map(|s| (Some(s), None)),
            ]
            .prop_map(|(src, body)| Script {
                src,
                body,
                span: Span::NONE,
            })
            .boxed()
        }
    }

    fn script_exec(&self) -> BoxedStrategy<Exec> {
        let k = self.script().prop_map(ExecKind::Script).boxed();
        self.with_exts(k, false)
    }

    fn if_exec(&self, block: BoxedStrategy<Vec<Exec>>) -> BoxedStrategy<Exec> {
        let branch = (arb_expr(), block.clone()).prop_map(|(c, body)| IfBranch {
            cond: Some(c),
            body,
            span: Span::NONE,
        });
        let k = if self.any {
            vec(
                (option::of(arb_expr()), block).prop_map(|(cond, body)| IfBranch {
                    cond,
                    body,
                    span: Span::NONE,
                }),
                0..=3,
            )
            .prop_map(|branches| ExecKind::If { branches })
            .boxed()
        } else {
            (vec(branch, 1..=2), option::of(block))
                .prop_map(|(mut branches, els)| {
                    if let Some(body) = els {
                        branches.push(IfBranch {
                            cond: None,
                            body,
                            span: Span::NONE,
                        });
                    }
                    ExecKind::If { branches }
                })
                .boxed()
        };
        self.with_exts(k, false)
    }

    fn foreach_exec(&self, block: BoxedStrategy<Vec<Exec>>) -> BoxedStrategy<Exec> {
        let k = (arb_expr(), self.name(), option::of(self.name()), block)
            .prop_map(|(array, item, index, body)| ExecKind::Foreach {
                array,
                item,
                index,
                body,
            })
            .boxed();
        self.with_exts(k, false)
    }

    // ------------------------------------------------------------ data, params, content

    fn param(&self) -> BoxedStrategy<Param> {
        (self.name(), self.one_of(arb_expr(), self.name()))
            .prop_map(|(name, (expr, location))| Param {
                name,
                expr,
                location,
                span: Span::NONE,
            })
            .boxed()
    }

    fn content(&self) -> BoxedStrategy<Content> {
        let pair = if self.any {
            (option::of(arb_expr()), option::of(self.body())).boxed()
        } else {
            prop_oneof![
                Just((None, None)),
                arb_expr().prop_map(|e| (Some(e), None)),
                self.body().prop_map(|b| (None, Some(b))),
            ]
            .boxed()
        };
        pair.prop_map(|(expr, body)| Content {
            expr,
            body,
            span: Span::NONE,
        })
        .boxed()
    }

    fn data(&self) -> BoxedStrategy<Data> {
        let value = if self.any {
            (
                option::of("[a-z]{1,6}\\.json".boxed()),
                option::of(arb_expr()),
                option::of(self.body()),
            )
                .boxed()
        } else {
            prop_oneof![
                Just((None, None, None)),
                "[a-z]{1,6}\\.json".prop_map(|s| (Some(s), None, None)),
                arb_expr().prop_map(|e| (None, Some(e), None)),
                self.body().prop_map(|b| (None, None, Some(b))),
            ]
            .boxed()
        };
        (self.name(), value, self.ext_attrs())
            .prop_map(|(id, (src, expr, content), extensions)| Data {
                id,
                src,
                expr,
                content,
                extensions,
                span: Span::NONE,
            })
            .boxed()
    }

    fn donedata(&self) -> BoxedStrategy<DoneData> {
        let parts = if self.any {
            (option::of(self.content()), vec(self.param(), 0..=2)).boxed()
        } else {
            prop_oneof![
                self.content().prop_map(|c| (Some(c), Vec::new())),
                vec(self.param(), 0..=2).prop_map(|p| (None, p)),
            ]
            .boxed()
        };
        parts
            .prop_map(|(content, params)| DoneData {
                content,
                params,
                span: Span::NONE,
            })
            .boxed()
    }

    fn invoke(&self) -> BoxedStrategy<Invoke> {
        let ty = self.pair(
            prop_oneof![
                Just("scxml".to_owned()),
                Just("http://www.w3.org/TR/scxml/".to_owned())
            ]
            .boxed(),
            arb_expr(),
        );
        let id = self.pair(self.name(), self.name());
        let source = if self.any {
            (
                option::of("[a-z]{1,6}\\.scxml".boxed()),
                option::of(arb_expr()),
                option::of(self.content()),
            )
                .boxed()
        } else {
            prop_oneof![
                Just((None, None, None)),
                "[a-z]{1,6}\\.scxml".prop_map(|s| (Some(s), None, None)),
                arb_expr().prop_map(|e| (None, Some(e), None)),
                self.content().prop_map(|c| (None, None, Some(c))),
            ]
            .boxed()
        };
        let pass = if self.any {
            (self.tokens(2), vec(self.param(), 0..=2)).boxed()
        } else {
            prop_oneof![
                self.tokens(2).prop_map(|n| (n, Vec::new())),
                vec(self.param(), 0..=2).prop_map(|p| (Vec::new(), p)),
            ]
            .boxed()
        };
        (
            ty,
            id,
            source,
            pass,
            any::<bool>(),
            self.block(),
            self.exts(),
        )
            .prop_map(
                |(
                    ty,
                    id,
                    (src, srcexpr, content),
                    (namelist, params),
                    autoforward,
                    finalize,
                    extensions,
                )| Invoke {
                    type_: ty.0,
                    typeexpr: ty.1,
                    src,
                    srcexpr,
                    id: id.0,
                    idlocation: id.1,
                    namelist,
                    autoforward,
                    params,
                    content,
                    finalize,
                    extensions,
                    span: Span::NONE,
                },
            )
            .boxed()
    }

    // ------------------------------------------------------------ transitions and states

    fn transition(&self, max_targets: usize) -> BoxedStrategy<Transition> {
        let kind = prop_oneof![
            Just((TransitionType::External, false)),
            Just((TransitionType::External, true)),
            Just((TransitionType::Internal, true)),
        ];
        let kind = if self.any {
            (
                prop_oneof![
                    Just(TransitionType::External),
                    Just(TransitionType::Internal)
                ],
                any::<bool>(),
            )
                .boxed()
        } else {
            kind.boxed()
        };
        (
            vec(arb_event_descriptor(), 0..=2),
            option::of(arb_expr()),
            vec(self.target(), 0..=max_targets),
            kind,
            self.block(),
            if self.any {
                self.exts()
            } else {
                self.ext_attrs()
            },
        )
            .prop_map(
                |(events, cond, targets, (kind, kind_explicit), body, extensions)| Transition {
                    events,
                    cond,
                    targets,
                    kind,
                    kind_explicit,
                    body,
                    extensions,
                    span: Span::NONE,
                },
            )
            .boxed()
    }

    /// A transition with no event and no condition and exactly one target (for `<initial>`
    /// and history defaults).
    fn default_transition(&self) -> BoxedStrategy<Transition> {
        if self.any {
            return self.transition(2);
        }
        (self.target(), self.block(), self.ext_attrs())
            .prop_map(|(t, body, extensions)| Transition {
                targets: vec![t],
                body,
                extensions,
                ..Transition::default()
            })
            .boxed()
    }

    /// An identifier: in the well-formed flavour, empty (anonymous) or a placeholder that is
    /// renamed later; in the any flavour, from a small pool.
    fn id(&self) -> BoxedStrategy<String> {
        if self.any {
            prop_oneof![Just(String::new()), "s[0-9]", "_vt\\.s(\\.[0-3]){1,2}_?"].boxed()
        } else {
            prop_oneof![1 => Just(String::new()), 3 => Just("x".to_owned())].boxed()
        }
    }

    fn common(&self) -> BoxedStrategy<State> {
        let invokes = if self.cfg.invokes {
            vec(self.invoke(), 0..=1).boxed()
        } else {
            Just(Vec::new()).boxed()
        };
        (
            self.id(),
            vec(
                self.transition(self.cfg.max_targets),
                0..=self.cfg.max_transitions,
            ),
            vec(self.block(), 0..=1),
            vec(self.block(), 0..=1),
            vec(self.data(), 0..=2),
            invokes,
            self.exts(),
        )
            .prop_map(
                |(id, transitions, onentry, onexit, data, invokes, extensions)| {
                    let mut s = State::new(id, StateElement::State);
                    s.transitions = transitions;
                    s.onentry = onentry;
                    s.onexit = onexit;
                    s.data = data;
                    s.invokes = invokes;
                    s.extensions = extensions;
                    s
                },
            )
            .boxed()
    }

    fn final_state(&self) -> BoxedStrategy<State> {
        (
            self.id(),
            vec(self.block(), 0..=1),
            vec(self.block(), 0..=1),
            option::of(self.donedata()),
            self.exts(),
        )
            .prop_map(|(id, onentry, onexit, donedata, extensions)| {
                let mut s = State::new(id, StateElement::Final);
                s.onentry = onentry;
                s.onexit = onexit;
                s.donedata = donedata;
                s.extensions = extensions;
                s
            })
            .boxed()
    }

    fn history(&self) -> BoxedStrategy<State> {
        (
            self.id(),
            any::<bool>(),
            option::of(self.default_transition()),
            self.exts(),
        )
            .prop_map(|(id, deep, default, extensions)| {
                let h = if deep {
                    HistoryType::Deep
                } else {
                    HistoryType::Shallow
                };
                let mut s = State::new(id, StateElement::History(h));
                s.transitions = default.into_iter().collect();
                s.extensions = extensions;
                s
            })
            .boxed()
    }

    fn initial_element(&self) -> BoxedStrategy<Initial> {
        (self.default_transition(), self.exts())
            .prop_map(|(transition, extensions)| Initial {
                transition,
                extensions,
                span: Span::NONE,
            })
            .boxed()
    }

    fn state(&self) -> BoxedStrategy<State> {
        if self.any {
            return self.any_state();
        }
        let g = self.clone();
        let leaf = prop_oneof![3 => self.common(), 1 => self.final_state()];
        let max_children = self.cfg.max_children;
        leaf.prop_recursive(
            self.cfg.max_depth,
            32,
            u32::try_from(max_children).unwrap_or(3),
            move |inner| {
                let children = vec(inner, 1..=max_children);
                let history = option::of((g.history(), any::<Index>()));
                let initial = prop_oneof![Just(0u8), Just(1u8), Just(2u8),];
                (
                    g.common(),
                    children,
                    history,
                    initial,
                    g.target(),
                    g.initial_element(),
                    any::<bool>(),
                )
                    .prop_map(
                        |(mut s, mut children, history, initial, t, ie, parallel)| {
                            if let Some((h, at)) = history {
                                let at = at.index(children.len() + 1);
                                children.insert(at, h);
                            }
                            s.children = children;
                            if parallel {
                                s.element = StateElement::Parallel;
                            } else {
                                match initial {
                                    1 => s.initial = vec![t],
                                    2 => s.initial_element = Some(ie),
                                    _ => {}
                                }
                            }
                            s
                        },
                    )
            },
        )
        .boxed()
    }

    fn any_state(&self) -> BoxedStrategy<State> {
        let g = self.clone();
        let element = prop_oneof![
            Just(StateElement::State),
            Just(StateElement::Parallel),
            Just(StateElement::Final),
            Just(StateElement::History(HistoryType::Shallow)),
            Just(StateElement::History(HistoryType::Deep)),
        ];
        let leaf = (self.common(), element.clone()).prop_map(|(mut s, e)| {
            s.element = e;
            s
        });
        let max_children = self.cfg.max_children;
        leaf.prop_recursive(
            self.cfg.max_depth,
            32,
            u32::try_from(max_children).unwrap_or(3),
            move |inner| {
                (
                    g.common(),
                    element.clone(),
                    vec(inner, 0..=max_children),
                    vec(g.target(), 0..=2),
                    option::of(g.initial_element()),
                    option::of(g.donedata()),
                    any::<bool>(),
                )
                    .prop_map(
                        |(mut s, e, children, initial, ie, dd, generated)| {
                            s.element = e;
                            s.children = children;
                            s.initial = initial;
                            s.initial_element = ie;
                            s.donedata = dd;
                            s.id_generated = generated;
                            s
                        },
                    )
            },
        )
        .boxed()
    }

    fn chart(&self) -> BoxedStrategy<Chart> {
        let datamodel = prop::sample::select(self.cfg.datamodels.clone());
        let flags = if self.any {
            (any::<bool>(), any::<bool>(), any::<bool>()).boxed()
        } else {
            (any::<bool>(), any::<bool>(), any::<bool>())
                .prop_map(|(dm_explicit, late, binding_explicit)| {
                    (dm_explicit, late, binding_explicit || late)
                })
                .boxed()
        };
        let any = self.any;
        let script = option::of(self.script());
        (
            option::of(self.name()),
            datamodel,
            flags,
            vec(self.target(), 0..=1),
            vec(self.data(), 0..=2),
            script,
            vec(self.state(), 1..=self.cfg.max_top_states),
            self.exts(),
        )
            .prop_map(
                move |(
                    name,
                    datamodel,
                    (dm_explicit, late, binding_explicit),
                    initial,
                    data,
                    script,
                    states,
                    extensions,
                )| {
                    let datamodel_explicit = if any {
                        dm_explicit
                    } else {
                        dm_explicit || datamodel != "null"
                    };
                    Chart {
                        name,
                        datamodel,
                        datamodel_explicit,
                        binding: if late { Binding::Late } else { Binding::Early },
                        binding_explicit,
                        initial,
                        data,
                        script,
                        states,
                        extensions,
                        span: Span::NONE,
                    }
                },
            )
            .boxed()
    }
}

// ==================================================================== canonical XML bodies

/// A canonical XML body: one or two elements, optionally followed by non-whitespace text.
fn xml_body() -> BoxedStrategy<String> {
    (
        vec(xml_element(), 1..=2),
        option::of("[a-z0-9&<>]{1,6}".prop_filter("not ws", |s: &String| !s.trim().is_empty())),
    )
        .prop_map(|(els, tail)| {
            let mut s = els.concat();
            if let Some(t) = tail {
                escape_text(&t, &mut s);
            }
            s
        })
        .boxed()
}

/// A canonical XML element: unprefixed (interpreted in the SCXML default namespace) or with a
/// prefix declared on itself.
fn xml_element() -> BoxedStrategy<String> {
    (any::<bool>(), "[a-z]{1,5}", xml_children())
        .prop_map(|(prefixed, local, rest)| {
            if prefixed {
                format!(
                    "<p:{local} xmlns:p=\"urn:example:payload\"{}",
                    close_element(&format!("p:{local}"), &rest)
                )
            } else {
                format!("<{local}{}", close_element(&local, &rest))
            }
        })
        .boxed()
}

/// Attributes and children of an element, rendered after its name by [`close_element`].
#[derive(Clone, Debug)]
struct XmlRest {
    attrs: Vec<(String, String)>,
    text: Option<String>,
    child: Option<String>,
}

fn xml_children() -> BoxedStrategy<XmlRest> {
    (
        vec(("[a-z]{1,4}", "[a-zA-Z0-9 &<>\"'\n]{0,6}"), 0..=2),
        option::of("[a-zA-Z0-9 &<>]{1,6}"),
        option::of("[a-z]{1,4}"),
    )
        .prop_map(|(attrs, text, child)| {
            let mut seen = BTreeSet::new();
            let attrs = attrs
                .into_iter()
                .filter(|(k, _)| seen.insert(k.clone()))
                .collect();
            XmlRest {
                attrs,
                text,
                child: child.map(|c| format!("<{c}/>")),
            }
        })
        .boxed()
}

fn close_element(qname: &str, rest: &XmlRest) -> String {
    let mut s = String::new();
    for (k, v) in &rest.attrs {
        s.push(' ');
        s.push_str(k);
        s.push_str("=\"");
        escape_attr(v, &mut s);
        s.push('"');
    }
    if rest.text.is_none() && rest.child.is_none() {
        s.push_str("/>");
        return s;
    }
    s.push('>');
    if let Some(t) = &rest.text {
        escape_text(t, &mut s);
    }
    if let Some(c) = &rest.child {
        s.push_str(c);
    }
    s.push_str("</");
    s.push_str(qname);
    s.push('>');
    s
}

fn escape_text(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '\r' => out.push_str("&#13;"),
            c => out.push(c),
        }
    }
}

fn escape_attr(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\t' => out.push_str("&#9;"),
            '\n' => out.push_str("&#10;"),
            '\r' => out.push_str("&#13;"),
            c => out.push(c),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::test_runner::{Config, TestRunner};

    fn check_well_formed(c: &Chart) -> Result<(), String> {
        let ids = state_ids(c);
        let unique: BTreeSet<&String> = ids.iter().collect();
        if unique.len() != ids.len() {
            return Err(format!("duplicate ids {ids:?}"));
        }
        fn data_ids(states: &[State], out: &mut Vec<String>) {
            for s in states {
                out.extend(s.data.iter().map(|d| d.id.clone()));
                data_ids(&s.children, out);
            }
        }
        let mut dids: Vec<String> = c.data.iter().map(|d| d.id.clone()).collect();
        data_ids(&c.states, &mut dids);
        if dids.iter().collect::<BTreeSet<_>>().len() != dids.len() {
            return Err(format!("duplicate data ids {dids:?}"));
        }
        fn walk(states: &[State], ids: &[String], top: bool) -> Result<(), String> {
            for s in states {
                if s.id.is_empty() {
                    return Err("empty id".into());
                }
                if top && is_history(s) {
                    return Err("history at root".into());
                }
                for t in &s.transitions {
                    for target in &t.targets {
                        if !ids.contains(target) {
                            return Err(format!("unknown target {target}"));
                        }
                    }
                }
                if matches!(s.element, StateElement::Final)
                    && (!s.children.is_empty() || !s.transitions.is_empty())
                {
                    return Err("final with children or transitions".into());
                }
                if matches!(s.element, StateElement::Parallel | StateElement::State)
                    && !s.children.is_empty()
                    && s.children.iter().all(is_history)
                {
                    return Err("history-only children".into());
                }
                let mut desc = Vec::new();
                descendants(s, &mut desc);
                for i in &s.initial {
                    if !desc.contains(i) {
                        return Err(format!("initial {i} not a descendant of {}", s.id));
                    }
                }
                walk(&s.children, ids, false)?;
            }
            Ok(())
        }
        walk(&c.states, &ids, true)
    }

    #[test]
    fn well_formed_charts_satisfy_the_structural_rules() {
        let mut runner = TestRunner::new(Config {
            cases: 128,
            ..Config::default()
        });
        runner
            .run(&arb_chart(), |c| {
                check_well_formed(&c).map_err(proptest::test_runner::TestCaseError::fail)
            })
            .expect("generated charts are well-formed");
    }

    #[test]
    fn any_charts_generate() {
        let mut runner = TestRunner::new(Config {
            cases: 64,
            ..Config::default()
        });
        runner
            .run(&arb_any_chart(), |c| {
                prop_assert!(!c.states.is_empty());
                Ok(())
            })
            .expect("any-IR charts generate");
    }

    #[test]
    fn canonicalization_is_idempotent() {
        let mut runner = TestRunner::default();
        runner
            .run(&arb_chart(), |c| {
                let mut d = c.clone();
                canonicalize_extensions(&mut d);
                prop_assert_eq!(c, d);
                Ok(())
            })
            .expect("canonical form is a fixpoint");
    }
}
